fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // Preconditions (as per problem statement):
    // - v is sorted in nondecreasing order
    // - k appears at least once in v

    let mut lo: usize = 0;
    let mut hi: usize = v.len(); // search in [lo, hi)

    // Find the first index i such that v[i] >= k (lower_bound).
    while lo < hi {
        let mid = lo + (hi - lo) / 2; // avoids overflow
        if v[mid] < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    // With the given precondition that k exists in v, lo is in-bounds and v[lo] == k.
    debug_assert!(lo < v.len());
    debug_assert!(v[lo] == k);

    lo
}